			AssertEquals("There is a Customs Declaration Information FTX", 1, cuspmt.AmendFields.Length);
			AssertEquals("The formatted string is", "INWARD HOUSE BILL OF LADING/HOUSE UNIQUE CARGO REFERENCE NUMBER/HOUSE AIR WAYBILL 01 (MODIFICATION)", cuspmt.AmendFields[0]);
		}

		public void TestMultipleAmendedFields()
		{
			CUSPMT cuspmt = new CUSPMT();
			cuspmt.Parse(new UNOASGCharacterSet(), MultipleAmendedFieldsMessage);
			AssertEquals("There is a Customs Declaration Information FTX", 4, cuspmt.AmendFields.Length);
			AssertEquals("The formatted string is", "DECLARANT CODE (MODIFICATION)", cuspmt.AmendFields[0]);
			AssertEquals("The formatted string is", "DECLARANT NAME (MODIFICATION)", cuspmt.AmendFields[1]);
			AssertEquals("The formatted string is", "OUTWARD VOYAGE NUMBER/FLIGHT NUMBER/REGISTRATION NUMBER (MODIFICATION)", cuspmt.AmendFields[2]);
			AssertEquals("The formatted string is", "SENDER ID (MODIFICATION)", cuspmt.AmendFields[3]);
		}

