		public void TestContainersFields()
		{
			CUSPMT cuspmt = new CUSPMT();
			cuspmt.Parse(new UNOASGCharacterSet(), ContainersMessage);
			AssertEquals(1, cuspmt.ContainerIdentifiers.Length);
			AssertEquals("ABCD1234 FCL 40 012 SEAL1", cuspmt.ContainerIdentifiers[0].ContainerIdentifier1);
			AssertEquals("EFGH5678 FCL 45 012 SEAL2", cuspmt.ContainerIdentifiers[0].ContainerIdentifier2);
			AssertEquals("01)", cuspmt.ContainerIdentifiers[0].ContainerSequenceNumber1);
			AssertEquals("02)", cuspmt.ContainerIdentifiers[0].ContainerSequenceNumber2);
			cuspmt = new CUSPMT();
			cuspmt.Parse(new UNOASGCharacterSet(), ContainersMessageThreeContainers);
			AssertEquals(2, cuspmt.ContainerIdentifiers.Length);
			AssertEquals("ABCD1234 FCL 40 012 SEAL1", cuspmt.ContainerIdentifiers[0].ContainerIdentifier1);
			AssertEquals("EFGH5678 FCL 45 012 SEAL2", cuspmt.ContainerIdentifiers[0].ContainerIdentifier2);
			AssertEquals("01)", cuspmt.ContainerIdentifiers[0].ContainerSequenceNumber1);
			AssertEquals("02)", cuspmt.ContainerIdentifiers[0].ContainerSequenceNumber2);
			AssertEquals("EFGH5679 FCL 45 001 ", cuspmt.ContainerIdentifiers[1].ContainerIdentifier1);
			AssertEquals("", cuspmt.ContainerIdentifiers[1].ContainerIdentifier2);
			AssertEquals("03)", cuspmt.ContainerIdentifiers[1].ContainerSequenceNumber1);
			AssertEquals("", cuspmt.ContainerIdentifiers[1].ContainerSequenceNumber2);
		}

